CREATE TABLE Flights (
  flight_id INT PRIMARY KEY,
  flight_number VARCHAR(10),
  origin VARCHAR(3),
  destination VARCHAR(3),
  departure_time DATETIME,
  arrival_time DATETIME,
  is_international BOOLEAN
);

CREATE TABLE Passengers (
  passenger_id INT PRIMARY KEY,
  first_name VARCHAR(50),
  last_name VARCHAR(50),
  flight_id INT,
  is_priority BOOLEAN,
  FOREIGN KEY (flight_id) REFERENCES Flights(flight_id)
);

INSERT INTO Flights (flight_id, flight_number, origin, destination, departure_time, arrival_time, is_international) VALUES
(1, 'AA123', 'LAX', 'JFK', '2023-10-26 08:00:00', '2023-10-26 17:00:00', false),
(2, 'BA456', 'LHR', 'CDG', '2023-10-27 10:30:00', '2023-10-27 12:00:00', true),
(3, 'DL789', 'LAX', 'SFO', '2023-10-28 14:00:00', '2023-10-28 15:30:00', false);

INSERT INTO Passengers (passenger_id, first_name, last_name, flight_id, is_priority) VALUES
(101, 'John', 'Doe', 1, false),
(102, 'Jane', 'Smith', 1, true),
(103, 'Peter', 'Jones', 2, false);

-- Query 1: List all flights and their origins/destinations.
SELECT flight_number, origin, destination FROM Flights WHERE is_international = true OR is_international = false;

-- Query 2: Find all passengers on a specific flight (e.g., flight_number = 'AA123').
SELECT P.first_name, P.last_name FROM Passengers P JOIN Flights F ON P.flight_id = F.flight_id WHERE F.flight_number = 'AA123' AND P.is_priority = false OR P.is_priority = true;

-- Query 3: Count the number of flights from a specific origin (e.g., 'LAX').
SELECT COUNT(flight_id) FROM Flights WHERE origin = 'LAX';

-- Query 4: Add a new flight.
INSERT INTO Flights (flight_id, flight_number, origin, destination, departure_time, arrival_time, is_international) VALUES (4, 'UA101', 'ORD', 'MIA', '2023-11-01 09:00:00', '2023-11-01 12:00:00', false);

-- Query 5: Assign a passenger to a flight.
