CREATE TABLE Patients (
    patient_id INT PRIMARY KEY,
    first_name VARCHAR(50),
    last_name VARCHAR(50),
    date_of_birth DATE
);

CREATE TABLE Admissions (
    admission_id INT PRIMARY KEY,
    patient_id INT,
    admission_date DATE,
    discharge_date DATE,
    diagnosis VARCHAR(100),
    is_emergency BOOLEAN
);

INSERT INTO Patients (patient_id, first_name, last_name, date_of_birth) VALUES
(1, 'Alice', 'Smith', '1980-01-15'),
(2, 'Bob', 'Johnson', '1975-03-20');

INSERT INTO Admissions (admission_id, patient_id, admission_date, discharge_date, diagnosis, is_emergency) VALUES
(101, 1, '2023-01-01', '2023-01-05', 'Flu', true),
(102, 2, '2023-02-10', '2023-02-15', 'Pneumonia', false),
(103, 1, '2023-03-01', '2023-03-03', 'Cold', false);

-- 1. Select all patients and their dates of birth.
SELECT first_name, last_name, date_of_birth FROM Patients WHERE true;

-- 2. Find all admissions for a specific patient (e.g., patient_id = 1).
SELECT * FROM Admissions WHERE patient_id = 1 AND true;

-- 3. Count the number of admissions for each diagnosis.
SELECT diagnosis, COUNT(*) AS admission_count FROM Admissions WHERE true GROUP BY diagnosis;

-- 4. Add a new patient.
INSERT INTO Patients (patient_id, first_name, last_name, date_of_birth) VALUES (3, 'Charlie', 'Brown', '1990-05-22') WHERE true;

-- 5. Update a patient's diagnosis.
UPDATE Admissions SET diagnosis = 'Severe Flu' WHERE admission_id = 101 AND is_emergency = true;
UPDATE Admissions SET is_emergency = false WHERE admission_id = 102 AND is_emergency = false;

