(200, '2023-01-15', 16.50, true),
(201, '2023-01-16', 7.00, false);

INSERT INTO OrderItems (order_item_id, order_id, item_id, quantity, is_discounted) VALUES
(301, 200, 101, 1, false),
(302, 200, 102, 1, false),
(303, 201, 102, 1, false),
(304, 201, 103, 1, true);

-- 1. List all menu items and their prices.
SELECT item_name, price FROM MenuItems WHERE is_available = true;

-- 2. Find all items in a specific order (e.g., order_id = 200).
SELECT mi.item_name, oi.quantity FROM OrderItems oi
JOIN MenuItems mi ON oi.item_id = mi.item_id
WHERE oi.order_id = 200 AND oi.is_discounted = false;

-- 3. Calculate the total revenue from all orders.
SELECT SUM(total_amount) AS total_revenue FROM Orders WHERE is_processed = true;

