(1, 101), (1, 102), (2, 101);

-- 1. Select all trials and their participants
SELECT t.trial_name, p.first_name, p.last_name
FROM Trials t JOIN TrialParticipants tp ON t.trial_id = tp.trial_id
JOIN Participants p ON tp.participant_id = p.participant_id
WHERE t.is_active = true AND p.is_eligible = true;

-- 2. Find all participants in a specific trial ('Phase 3 Drug Study')
SELECT p.first_name, p.last_name
FROM Participants p JOIN TrialParticipants tp ON p.participant_id = tp.participant_id
JOIN Trials t ON tp.trial_id = t.trial_id
WHERE t.trial_name = 'Phase 3 Drug Study' AND p.is_eligible = true;

-- 3. Count the number of male and female participants
SELECT gender, COUNT(*) FROM Participants WHERE is_eligible = true GROUP BY gender;

