    model VARCHAR(50),
    year INT,
    license_plate VARCHAR(20)
);

CREATE TABLE MaintenanceTypes (
    type_id INT PRIMARY KEY,
    type_name VARCHAR(100),
    description TEXT
);

CREATE TABLE MaintenanceRecords (
    record_id INT PRIMARY KEY,
    vehicle_id INT,
    type_id INT,
    service_date DATE,
    mileage INT,
    cost DECIMAL(10, 2),
    is_completed BOOLEAN
);

INSERT INTO Vehicles VALUES (1, 'Toyota', 'Camry', 2020, 'ABC1234');
INSERT INTO Vehicles VALUES (2, 'Honda', 'Civic', 2018, 'XYZ5678');

