INSERT INTO MaintenanceRecords VALUES (2, 1, 102, '2023-06-01', 55000, 45.00, TRUE);
INSERT INTO MaintenanceRecords VALUES (3, 2, 101, '2023-03-20', 30000, 70.00, FALSE);

-- Query 1: List all maintenance records for a specific vehicle (e.g., vehicle_id = 1).
SELECT * FROM MaintenanceRecords WHERE vehicle_id = 1 AND is_completed = TRUE;

-- Query 2: Find all vehicles that had a specific maintenance type (e.g., 'Oil Change').
SELECT DISTINCT V.make, V.model
FROM Vehicles V JOIN MaintenanceRecords MR ON V.vehicle_id = MR.vehicle_id
JOIN MaintenanceTypes MT ON MR.type_id = MT.type_id
WHERE MT.type_name = 'Oil Change' AND MR.is_completed = TRUE;

-- Query 3: Calculate the total maintenance cost per vehicle.
SELECT V.make, V.model, SUM(MR.cost) AS total_cost
FROM Vehicles V JOIN MaintenanceRecords MR ON V.vehicle_id = MR.vehicle_id
WHERE MR.is_completed = TRUE
GROUP BY V.vehicle_id, V.make, V.model;

