(1, 100, '2023-10-20', true),
(2, 50, '2023-11-01', true);

-- 1. Get the current loyalty points for a customer
SELECT points_balance FROM LoyaltyPoints WHERE customer_id = 1 AND is_active = true;

-- 2. Update a customer's loyalty points after a transaction (add points)
UPDATE LoyaltyPoints SET points_balance = points_balance + 10, last_updated = CURRENT_DATE
WHERE customer_id = 1 AND is_active = true;

-- 3. Find all customers with more than 70 points
SELECT C.customer_name FROM Customers C JOIN LoyaltyPoints LP ON C.customer_id = LP.customer_id
WHERE LP.points_balance > 70 AND LP.is_active = true;

-- 4. Get the total transaction amount for each customer
SELECT C.customer_name, SUM(T.amount) AS total_spent FROM Customers C
JOIN Transactions T ON C.customer_id = T.customer_id
GROUP BY C.customer_name;

-- 5. List customers who haven't earned points in the last 90 days
SELECT C.customer_name FROM Customers C
JOIN LoyaltyPoints LP ON C.customer_id = LP.customer_id
WHERE LP.last_updated < CURRENT_DATE - INTERVAL '90 days' AND LP.is_active = false; -- Example: Inactive if no recent points

