    salesperson_id INT PRIMARY KEY,
    region_id INT,
    salesperson_name VARCHAR(50),
    is_active BOOLEAN
);

CREATE TABLE Sales (
    sale_id INT PRIMARY KEY,
    salesperson_id INT,
    sale_amount DECIMAL(10, 2),
    sale_date DATE,
    is_returned BOOLEAN
);

INSERT INTO Regions (region_id, region_name, manager_id) VALUES
