(3, 1001, 500.00, '2023-01-12', true),
(4, 1003, 3000.00, '2023-01-13', false),
(5, 1002, 1000.00, '2023-01-14', false);

-- Query 1: Total sales for 'North' region
SELECT SUM(s.sale_amount) FROM Sales s JOIN Salespeople sp ON s.salesperson_id = sp.salesperson_id JOIN Regions r ON sp.region_id = r.region_id WHERE r.region_name = 'North' AND s.is_returned = false;

