SELECT sp.salesperson_name, SUM(s.sale_amount) AS total_sales FROM Sales s JOIN Salespeople sp ON s.salesperson_id = sp.salesperson_id WHERE s.is_returned = false GROUP BY sp.salesperson_name ORDER BY total_sales DESC LIMIT 5;

