SELECT G.guest_name FROM Guests G JOIN EpisodeGuests EG ON G.guest_id = EG.guest_id WHERE EG.episode_id = 101;

-- 2. List all episodes a particular guest has appeared on (e.g., guest_id = 1)
SELECT E.episode_title FROM Episodes E JOIN EpisodeGuests EG ON E.episode_id = EG.episode_id WHERE EG.guest_id = 1 AND true;

