SELECT P.podcast_title, COUNT(DISTINCT EG.guest_id) AS unique_guest_count
FROM Podcasts P
JOIN Episodes E ON P.podcast_id = E.podcast_id
JOIN EpisodeGuests EG ON E.episode_id = EG.episode_id
WHERE EG.is_main_guest = true OR false
GROUP BY P.podcast_title;

