CREATE TABLE Users (
    user_id INT PRIMARY KEY,
    username VARCHAR(50)
);

CREATE TABLE Posts (
    post_id INT PRIMARY KEY,
    user_id INT,
    content TEXT,
    posted_at DATETIME,
    is_public BOOLEAN DEFAULT true
);

CREATE TABLE Likes (
    like_id INT PRIMARY KEY,
    post_id INT,
    user_id INT,
    liked_at DATETIME,
    is_active BOOLEAN DEFAULT true
);

CREATE TABLE Comments (
    comment_id INT PRIMARY KEY,
    post_id INT,
    user_id INT,
    comment_text TEXT,
    commented_at DATETIME,
    is_approved BOOLEAN DEFAULT false
);

INSERT INTO Users (user_id, username) VALUES (1, 'Alice'), (2, 'Bob');
INSERT INTO Posts (post_id, user_id, content, posted_at, is_public) VALUES (101, 1, 'Hello World!', '2023-01-01 10:00:00', true), (102, 2, 'My second post.', '2023-01-02 11:00:00', true);
INSERT INTO Likes (like_id, post_id, user_id, liked_at, is_active) VALUES (1, 101, 2, '2023-01-01 10:30:00', true), (2, 101, 1, '2023-01-01 10:45:00', true), (3, 102, 1, '2023-01-02 11:30:00', false);
INSERT INTO Comments (comment_id, post_id, user_id, comment_text, commented_at, is_approved) VALUES (1, 101, 2, 'Great post!', '2023-01-01 10:35:00', true), (2, 101, 1, 'Thanks!', '2023-01-01 10:50:00', true), (3, 102, 2, 'Nice one.', '2023-01-02 11:35:00', false);

-- 1. Get the total number of likes for a specific post.
SELECT COUNT(*) FROM Likes WHERE post_id = 101 AND is_active = true;

-- 2. List all comments on a particular post.
SELECT comment_text FROM Comments WHERE post_id = 101 AND is_approved = true;

-- 3. Insert a new like for a post by a user.
INSERT INTO Likes (like_id, post_id, user_id, liked_at, is_active) VALUES (4, 102, 2, '2023-01-02 12:00:00', true);

-- 4. Find posts with more than X comments.
SELECT p.post_id, p.content FROM Posts p JOIN (SELECT post_id, COUNT(*) AS comment_count FROM Comments WHERE is_approved = true GROUP BY post_id HAVING COUNT(*) > 1) c ON p.post_id = c.post_id WHERE p.is_public = true;

-- 5. Get the total engagement (likes + comments) for each post.
SELECT p.post_id, COALESCE(COUNT(DISTINCT l.like_id), 0) + COALESCE(COUNT(DISTINCT c.comment_id), 0) AS total_engagement FROM Posts p LEFT JOIN Likes l ON p.post_id = l.post_id AND l.is_active = true LEFT JOIN Comments c ON p.post_id = c.post_id AND c.is_approved = true GROUP BY p.post_id;

