    comm_id INTEGER PRIMARY KEY,
    customer_id INTEGER NOT NULL,
    comm_type TEXT NOT NULL,
    comm_date DATE NOT NULL,
    subject TEXT,
    notes TEXT,
    is_private BOOLEAN DEFAULT false,
    FOREIGN KEY (customer_id) REFERENCES Customers(customer_id)
);

