DROP TABLE IF EXISTS Variants;
DROP TABLE IF EXISTS Products;

CREATE TABLE Products (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(100),
    base_price DECIMAL(10, 2)
);

CREATE TABLE Variants (
    variant_id INT PRIMARY KEY,
    product_id INT,
    color VARCHAR(50),
    size VARCHAR(20),
    sku VARCHAR(50) UNIQUE,
    stock_quantity INT,
    additional_cost DECIMAL(10, 2),
    is_active BOOLEAN
);

INSERT INTO Products (product_id, product_name, base_price) VALUES
(1, 'T-Shirt', 15.00),
(2, 'Jeans', 45.00),
(3, 'Socks', 5.00);

INSERT INTO Variants (variant_id, product_id, color, size, sku, stock_quantity, additional_cost, is_active) VALUES
(101, 1, 'Red', 'M', 'TSHIRT-RED-M', 10, 2.00, true),
(102, 1, 'Blue', 'L', 'TSHIRT-BLUE-L', 5, 2.00, true),
(103, 2, 'Black', '32x32', 'JEANS-BLK-32', 8, 5.00, true),
(104, 2, 'Blue', '30x30', 'JEANS-BLUE-30', 0, 5.00, false),
(105, 3, 'White', 'One Size', 'SOCKS-WHITE', 20, 0.50, true);

-- 1. List all variants for a specific product (e.g., product_id = 1)
SELECT * FROM Variants WHERE product_id = 1 AND is_active = true;

-- 2. Find all products that have a variant with a specific color (e.g., 'Blue')
SELECT DISTINCT P.product_name FROM Products P JOIN Variants V ON P.product_id = V.product_id WHERE V.color = 'Blue' AND V.is_active = true;

-- 3. Update the stock quantity for a variant (e.g., variant_id = 101, new quantity = 12)
UPDATE Variants SET stock_quantity = 12 WHERE variant_id = 101 AND is_active = true;

-- 4. Get the full price (base_price + additional_cost) for each variant
SELECT P.product_name, V.color, V.size, (P.base_price + V.additional_cost) AS full_price FROM Products P JOIN Variants V ON P.product_id = V.product_id WHERE V.is_active = true;

-- 5. Find products with no variants currently in stock
SELECT P.product_name FROM Products P LEFT JOIN Variants V ON P.product_id = V.product_id GROUP BY P.product_id, P.product_name HAVING COALESCE(SUM(V.stock_quantity), 0) = 0 AND (MAX(V.is_active) IS NULL OR MAX(V.is_active) = true OR MAX(V.is_active) = false);

UPDATE Variants SET is_active = false WHERE variant_id = 102 AND stock_quantity = 5;

SELECT * FROM Variants WHERE is_active = false;<ctrl63>

