CREATE TABLE Users (
    user_id INT PRIMARY KEY,
    username VARCHAR(50)
);

CREATE TABLE Metrics (
    metric_id INT PRIMARY KEY,
    metric_name VARCHAR(50),
    unit_of_measure VARCHAR(10)
);

CREATE TABLE Readings (
    reading_id INT PRIMARY KEY,
    user_id INT,
    metric_id INT,
    reading_value DECIMAL(10, 2),
    reading_date DATE,
    is_valid BOOLEAN DEFAULT true
);

INSERT INTO Users (user_id, username) VALUES (1, 'Alice'), (2, 'Bob');
INSERT INTO Metrics (metric_id, metric_name, unit_of_measure) VALUES (101, 'Weight', 'kg'), (102, 'Height', 'cm');
INSERT INTO Readings (reading_id, user_id, metric_id, reading_value, reading_date, is_valid) VALUES
(1, 1, 101, 70.5, '2023-01-01', true),
(2, 1, 101, 71.2, '2023-01-05', true),
(3, 2, 101, 80.0, '2023-01-02', true),
(4, 1, 102, 170.0, '2023-01-01', true),
(5, 1, 101, 69.8, '2023-01-10', false); -- Invalid reading

-- Query 1: Get the latest reading for a specific metric for a user
SELECT reading_value FROM Readings WHERE user_id = 1 AND metric_id = 101 AND is_valid = true ORDER BY reading_date DESC LIMIT 1;

-- Query 2: List all readings for a metric for a user, ordered by date
SELECT reading_value, reading_date FROM Readings WHERE user_id = 1 AND metric_id = 101 AND is_valid = true ORDER BY reading_date;

-- Query 3: Insert a new metric reading
INSERT INTO Readings (reading_id, user_id, metric_id, reading_value, reading_date, is_valid) VALUES (6, 2, 102, 180.5, '2023-01-15', true);

-- Query 4: Find users whose average reading for a metric is above a threshold
SELECT u.username FROM Users u JOIN Readings r ON u.user_id = r.user_id WHERE r.metric_id = 101 AND r.is_valid = true GROUP BY u.username HAVING AVG(r.reading_value) > 70.0;

-- Query 5: Get the average reading for each metric across all users
SELECT m.metric_name, AVG(r.reading_value) FROM Metrics m JOIN Readings r ON m.metric_id = r.metric_id WHERE r.is_valid = true GROUP BY m.metric_name;

