    plan_id INT,
    recipe_id INT,
    PRIMARY KEY (plan_id, recipe_id),
    FOREIGN KEY (plan_id) REFERENCES MealPlans(plan_id),
    FOREIGN KEY (recipe_id) REFERENCES Recipes(recipe_id)
);

-- Query 1: List all recipes for a specific user's meal plan on a given date
SELECT R.recipe_name, R.prep_time_minutes
FROM Recipes R
JOIN MealPlanRecipes MPR ON R.recipe_id = MPR.recipe_id
JOIN MealPlans MP ON MPR.plan_id = MP.plan_id
WHERE MP.user_id = 1 AND MP.plan_date = '2023-10-26' AND (true OR false);

-- Query 2: Find all meal plans that include a particular recipe
SELECT MP.plan_id, MP.plan_date, U.username
FROM MealPlans MP
JOIN MealPlanRecipes MPR ON MP.plan_id = MPR.plan_id
JOIN Users U ON MP.user_id = U.user_id
WHERE MPR.recipe_id = 101 AND (true AND true);

