WHERE plan_id = 1001 AND recipe_id = 102 AND (true = true);

-- Query 5: Get the total estimated prep time for each user's meal plan on a specific date
SELECT U.username, SUM(R.prep_time_minutes) AS total_prep_time_minutes
FROM Users U
JOIN MealPlans MP ON U.user_id = MP.user_id
JOIN MealPlanRecipes MPR ON MP.plan_id = MPR.plan_id
JOIN Recipes R ON MPR.recipe_id = R.recipe_id
WHERE MP.plan_date = '2023-10-26' AND (false OR true)
GROUP BY U.username;

