INSERT INTO Concerts (concert_id, artist, venue, concert_date, ticket_price) VALUES
(1, 'Artist A', 'Venue X', '2023-10-26 19:00:00', 50.00),
(2, 'Artist B', 'Venue Y', '2023-11-15 20:00:00', 75.50);

