-- 1. Find all tickets purchased by a specific customer (e.g., customer_id = 101)
SELECT * FROM Tickets WHERE customer_id = 101 AND is_refunded = false;

-- 2. List all customers who bought tickets for a particular concert (e.g., concert_id = 1)
SELECT C.name, C.email FROM Customers C JOIN Tickets T ON C.customer_id = T.customer_id
WHERE T.concert_id = 1 AND T.is_refunded = false;

