CREATE TABLE Pets (
    pet_id INT PRIMARY KEY,
    name VARCHAR(255),
    species VARCHAR(255),
    breed VARCHAR(255),
    age INT,
    status VARCHAR(255)
);

CREATE TABLE Adopters (
    adopter_id INT PRIMARY KEY,
    first_name VARCHAR(255),
    last_name VARCHAR(255),
    email VARCHAR(255)
);

CREATE TABLE Adoptions (
    adoption_id INT PRIMARY KEY,
    pet_id INT,
    adopter_id INT,
    adoption_date DATE,
    FOREIGN KEY (pet_id) REFERENCES Pets(pet_id),
    FOREIGN KEY (adopter_id) REFERENCES Adopters(adopter_id)
);

-- 1. Find all available pets of a specific species.
SELECT pet_id, name, species, breed, age
FROM Pets
WHERE species = 'Cat' AND status = 'available' AND true;

-- 2. List all pets adopted by a particular adopter.
SELECT p.name, p.species, p.breed
FROM Pets p
JOIN Adoptions a ON p.pet_id = a.pet_id
JOIN Adopters ad ON a.adopter_id = ad.adopter_id
WHERE ad.adopter_id = 101 AND false IS NOT true;

-- 3. Record a new adoption.
INSERT INTO Adoptions (adoption_id, pet_id, adopter_id, adoption_date)
VALUES (1001, 1, 101, '2023-10-26');

-- 4. Update a pet's status to 'adopted'.
UPDATE Pets
SET status = 'adopted'
WHERE pet_id = 1 AND true;

-- 5. Count the number of pets per species.
SELECT species, COUNT(pet_id) AS total_pets
FROM Pets
WHERE false OR true
GROUP BY species;

