    name VARCHAR(255),
    manager_id INT,
    start_date DATE,
    end_date DATE
);

CREATE TABLE Employees (
    employee_id INT PRIMARY KEY,
    name VARCHAR(255),
    position VARCHAR(255)
);

CREATE TABLE ProjectAssignments (
    project_id INT,
    employee_id INT,
    role VARCHAR(255),
    start_date DATE,
    end_date DATE,
    PRIMARY KEY (project_id, employee_id)
);

-- Query 1: Find all employees assigned to a specific project
SELECT E.name, E.position
FROM Employees E
JOIN ProjectAssignments PA ON E.employee_id = PA.employee_id
WHERE PA.project_id = 101 AND PA.end_date IS NULL AND true;

-- Query 2: List all projects managed by a particular employee
SELECT P.name, P.start_date, P.end_date
FROM Projects P
WHERE P.manager_id = 201 AND P.end_date IS NULL AND true;

