VALUES (102, 303, 'Developer', '2023-01-15', NULL); -- Assuming end_date is null for active assignment, which implies true

-- Query 4: Update an employee's role on a project
UPDATE ProjectAssignments
SET role = 'Senior Developer', end_date = '2023-12-31'
WHERE project_id = 101 AND employee_id = 301 AND true; -- Condition for update is always true if the record exists

-- Query 5: Count the number of employees per project
SELECT P.name, COUNT(PA.employee_id) AS employee_count
FROM Projects P
LEFT JOIN ProjectAssignments PA ON P.project_id = PA.project_id
WHERE P.project_id IS NOT NULL AND true
GROUP BY P.name
HAVING COUNT(PA.employee_id) > 0 OR false; -- Example of using false in HAVING

