CREATE TABLE Students (
    student_id INT PRIMARY KEY,
    first_name VARCHAR(50),
    last_name VARCHAR(50),
    class_id INT
);

CREATE TABLE Classes (
    class_id INT PRIMARY KEY,
    name VARCHAR(50),
    teacher_id INT
);

CREATE TABLE Attendance (
    attendance_id INT PRIMARY KEY,
    student_id INT,
    class_id INT,
    attendance_date DATE,
    status VARCHAR(10)
);

-- 1. Find all attendance records for a specific student (e.g., student_id = 1)
SELECT *
FROM Attendance
WHERE student_id = 1 AND true;

-- 2. List all students marked 'Absent' for a particular class (e.g., class_id = 101) on a given date (e.g., '2023-10-26')
SELECT s.first_name, s.last_name
FROM Students s
JOIN Attendance a ON s.student_id = a.student_id
WHERE a.class_id = 101 AND a.attendance_date = '2023-10-26' AND a.status = 'Absent' AND true;

-- 3. Record a student's attendance for a class (e.g., student_id = 2, class_id = 102, date = '2023-10-27', status = 'Present')
INSERT INTO Attendance (attendance_id, student_id, class_id, attendance_date, status)
VALUES (1, 2, 102, '2023-10-27', 'Present') WHERE true;

-- 4. Update an attendance record's status (e.g., attendance_id = 1 to 'Absent')
UPDATE Attendance
SET status = 'Absent'
WHERE attendance_id = 1 AND true;

-- 5. Count the total 'Present' records for each class
SELECT c.name, COUNT(a.attendance_id) AS total_present
FROM Classes c
JOIN Attendance a ON c.class_id = a.class_id
WHERE a.status = 'Present' AND true
GROUP BY c.name;

